def format_citations(cites: List[dict]) -> str:
    if not cites:
        return ""
    formatted = []
    for c in cites:
        content = c.get("content", "").strip()
        authors = c.get("concise_authors", "").strip()
        title   = c.get("title", "").strip()
        if not content:
            continue
        suffix = ""
        if authors and title:
            suffix = f" ({authors}, \"{title}\")"
        elif authors:
            suffix = f" ({authors})"
        elif title:
            suffix = f" (\"{title}\")"
        formatted.append(f"{content}{suffix}")
    return "\n".join(formatted).strip()

def build_fewshot_prompt(item: dict, n_shot: int = 0) -> str:
    head = (
        "You are an expert in scientific literature synthesis. "
        "Your task is to evaluate the quality of two AI-generated citation-attributed responses to a user's question. "
        "Assess both responses for relevance, accuracy, clarity, and appropriate use of citations. "
        "Then, select the response, Output (a) or Output (b), that best addresses the question.\n"
    )

    shots = ""
    n = min(n_shot, len(GOLD_EXAMPLES))
    for i in range(n):
        eg = GOLD_EXAMPLES[i]

        shot_block = (
            f"\nExample {i + 1}:\n"
            f"User Question:\n{eg['question']}\n\n"
            f"Output (a):\n{eg['responseA']}\n"
        )

        if INCLUDE_CITATIONS and eg.get("citations_a"):
            shot_block += f"\nCitations for (a):\n{format_citations(eg['citations_a'])}\n"

        shot_block += f"\nOutput (b):\n{eg['responseB']}\n"

        if INCLUDE_CITATIONS and eg.get("citations_b"):
            shot_block += f"\nCitations for (b):\n{format_citations(eg['citations_b'])}\n"

        shot_block += f"\nExpert choice: {eg['vote']}\n---\n"
        shots += shot_block

    tail = (
        "\nNow evaluate a new question in the same way. "
        "For the following, answer only with \"A\" or \"B\":\n\n"
        f"User Question:\n{item.get('question', '')}\n\n"
        f"Output (a):\n{item.get('responseA', '')}\n"
    )

    if INCLUDE_CITATIONS and item.get("citations_a"):
        tail += f"\nCitations for (a):\n{format_citations(item['citations_a'])}\n"

    tail += f"\nOutput (b):\n{item.get('responseB', '')}\n"

    if INCLUDE_CITATIONS and item.get("citations_b"):
        tail += f"\nCitations for (b):\n{format_citations(item['citations_b'])}\n"

    tail += (
        "\nWhich is best, Output(a) or Output(b)?\n"
        "Answer with only: \"A\" or \"B\""
    )

    return head + shots + tail

vote_pat = re.compile(r"\b([AB])\b", flags=re.I)

def normalize_vote(text: str) -> str:
    if not text:
        return ""
    m = vote_pat.search(text.strip())
    return m.group(1).upper() if m else ""


def score_one(idx: int, item: dict, n_shot: int) -> Tuple[int, dict]:
    if not (item.get("question") and item.get("responseA") and item.get("responseB")):
        item["predicted_output"] = ""
        return idx, item

    prompt = build_fewshot_prompt(item, n_shot=n_shot)

    for attempt in range(1, AZURE_CONF["RETRY"] + 1):
        try:
            resp = client.chat.completions.create(
                model    = AZURE_CONF["DEPLOY"],
                messages = [{"role": "user", "content": prompt}],
            )
            vote = normalize_vote(resp.choices[0].message.content)
            item["predicted_output"] = vote
            return idx, item

        except (APIError, APITimeoutError, Exception) as e:
            if attempt == AZURE_CONF["RETRY"]:
                print(f"[ERROR] idx={idx} failed after {attempt} tries: {e}")
                item["predicted_output"] = ""
            time.sleep(2 ** attempt)  

    return idx, item

def main() -> None:
    print(
        f"Few-shot setting: n_shot={N_SHOT} "
        f"(max available gold examples: {len(GOLD_EXAMPLES)}) | "
        f"Include citations: {INCLUDE_CITATIONS}"
    )

    if not INPUT_JSON.exists():
        raise FileNotFoundError(f"{INPUT_JSON} does not exist")

    with INPUT_JSON.open(encoding="utf-8") as f:
        data = json.load(f)

    results = [None] * len(data)

    with ThreadPoolExecutor(max_workers=AZURE_CONF["MAX_WORKERS"]) as pool:
        futures = {
            pool.submit(score_one, i, sample, N_SHOT): i
            for i, sample in enumerate(data)
        }

        for fut in tqdm(as_completed(futures), total=len(futures), desc="Scoring"):
            idx, scored_item = fut.result()
            results[idx] = scored_item

    with OUTPUT_JSON.open("w", encoding="utf-8") as f:
        json.dump(results, f, ensure_ascii=False, indent=2)

    print(f"Done ✔  Saved {len(results)} items to {OUTPUT_JSON}")


if __name__ == "__main__":
    main()